ce" min="0" max="10000" value="24" required></label><label class="field"><span>الأقسام</span><input type="number" name="max_sections" min="1" max="100" value="24" required></label></div><div class="owner-feature-grid"><label><input type="checkbox" name="ai_enabled" value="1" checked> المساعد</label><label><input type="checkbox" name="custom_templates_enabled" value="1" checked> القوالب المخصصة</label><label><input type="checkbox" name="public_sharing_enabled" value="1" checked> المشاركة</label><label><input type="checkbox" name="file_upload_enabled" value="1" checked> رفع الملفات</label><label><input type="checkbox" name="is_active" value="1" checked> متاحة</label></div><button class="button button-navy" type="submit">إضافة الخطة</button></form></article></div></section>
